// Auto-generated logo and favicon assets
function base64ToUint8Array(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export const LOGO_PNG_BASE64 = "";
export const FAVICON_PNG_BASE64 = "";
export const FAVICON_32_PNG_BASE64 = "";

export const LOGO_DATA_URL = "data:image/png;base64," + LOGO_PNG_BASE64;
export const FAVICON_DATA_URL = "data:image/png;base64," + FAVICON_PNG_BASE64;

let cachedLogoBytes: Uint8Array | null = null;
export function getLogoBytes(): Uint8Array {
  if (!cachedLogoBytes) cachedLogoBytes = base64ToUint8Array(LOGO_PNG_BASE64);
  return cachedLogoBytes;
}

let cachedFaviconBytes: Uint8Array | null = null;
export function getFaviconBytes(): Uint8Array {
  if (!cachedFaviconBytes) cachedFaviconBytes = base64ToUint8Array(FAVICON_PNG_BASE64);
  return cachedFaviconBytes;
}

let cachedFavicon32Bytes: Uint8Array | null = null;
export function getFavicon32Bytes(): Uint8Array {
  if (!cachedFavicon32Bytes) cachedFavicon32Bytes = base64ToUint8Array(FAVICON_32_PNG_BASE64);
  return cachedFavicon32Bytes;
}
